/* ============================================================
   La Trattoria — script du site public
   Aucune dependance externe : le site doit fonctionner sur le
   wifi du restaurant, sans internet.
   ============================================================ */
(function () {
  'use strict';

  var PANIER = [];
  var CRENEAU = null;
  var MODE = (window.TRATTORIA && window.TRATTORIA.mode) || 'statique';
  var API = (window.TRATTORIA && window.TRATTORIA.api) || '';
  var TEL = (window.TRATTORIA && window.TRATTORIA.tel) || '';

  // ==========================================================
  //  Correctif durci 11.1 : découverte automatique de l'API locale
  // ==========================================================
  // En mode « local », la page est servie par la tablette du restaurant
  // (port 8720). La version 11.0 n'injectait pas l'URL de l'API dans
  // window.TRATTORIA (api = ""), ce qui rendait la commande en ligne
  // inopérante : le script basculait systématiquement sur le repli
  // « commande par téléphone ». On retombe donc sur location.origin,
  // qui pointe toujours vers la tablette qui a servi la page.
  // En mode « statique » (site exporté, sans serveur local), API reste
  // vide et le repli téléphonique est conservé : aucun changement de
  // comportement.
  if (!API && MODE === 'local'
      && location.protocol === 'http:' && location.hostname) {
    API = location.origin;
  }

  // ==========================================================
  //  Retour haptique et sonore
  // ==========================================================

  /**
   * Vibration. Ignoree par iOS et par les navigateurs de bureau :
   * c'est un confort, jamais le seul canal d'information.
   */
  function vibrer(motif) {
    try { if (navigator.vibrate) navigator.vibrate(motif); } catch (e) { }
  }

  /**
   * Sons de synthese via WebAudio : aucun fichier a telecharger,
   * donc aucune latence au premier clic.
   * Le contexte n'est cree qu'au premier geste de l'utilisateur,
   * les navigateurs refusant tout son avant interaction.
   */
  var ctxAudio = null;
  var sonCoupe = false;
  function audio() {
    if (sonCoupe) return null;
    try {
      if (!ctxAudio) {
        var C = window.AudioContext || window.webkitAudioContext;
        if (!C) return null;
        ctxAudio = new C();
      }
      if (ctxAudio.state === 'suspended') ctxAudio.resume();
      return ctxAudio;
    } catch (e) { return null; }
  }

  function bip(freq, duree, volume, forme, retard) {
    var a = audio();
    if (!a) return;
    try {
      var o = a.createOscillator(), g = a.createGain();
      var t = a.currentTime + (retard || 0);
      o.type = forme || 'sine';
      o.frequency.setValueAtTime(freq, t);
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(volume || 0.13, t + 0.012);
      g.gain.exponentialRampToValueAtTime(0.0001, t + duree);
      o.connect(g); g.connect(a.destination);
      o.start(t); o.stop(t + duree + 0.02);
    } catch (e) { }
  }

  var SONS = {
    ajout:   function () { bip(880, 0.09, 0.11, 'sine'); vibrer(18); },
    retrait: function () { bip(420, 0.08, 0.09, 'sine'); vibrer(12); },
    clic:    function () { bip(660, 0.05, 0.06, 'sine'); vibrer(8); },
    succes:  function () {
      bip(659, 0.13, 0.12, 'sine', 0);
      bip(784, 0.13, 0.12, 'sine', 0.11);
      bip(1047, 0.26, 0.13, 'sine', 0.22);
      vibrer([28, 55, 28, 55, 90]);
    },
    refus:   function () {
      bip(280, 0.19, 0.13, 'triangle', 0);
      bip(190, 0.32, 0.13, 'triangle', 0.17);
      vibrer([90, 70, 90]);
    },
    alerte:  function () { bip(520, 0.11, 0.10, 'triangle'); vibrer([25, 45, 25]); }
  };

  function $(s, r) { return (r || document).querySelector(s); }
  function $$(s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); }

  function eur(v) {
    var n = Number(v);
    if (!isFinite(n)) n = 0;         // jamais « NaN € » a l'ecran
    return n.toFixed(2).replace('.', ',') + ' \u20ac';
  }

  // ==========================================================
  //  Notification breve
  // ==========================================================
  var minuteurToast;
  function toast(msg) {
    var t = $('#toast');
    if (!t) return;
    t.textContent = msg;
    t.classList.add('on');
    clearTimeout(minuteurToast);
    minuteurToast = setTimeout(function () { t.classList.remove('on'); }, 2600);
  }

  // ==========================================================
  //  Panier
  // ==========================================================
  function ajouter(id, nom, prix, bouton) {
    var l = null;
    for (var i = 0; i < PANIER.length; i++) if (PANIER[i].id === id) l = PANIER[i];
    if (l) {
      // meme plafond que le serveur, pour eviter un refus apres coup
      if (l.qte >= 30) { toast('Pour une telle quantite, appelez-nous'); return; }
      l.qte++;
    } else {
      if (PANIER.length >= 40) { toast('Panier trop grand, appelez-nous'); return; }
      PANIER.push({ id: id, nom: nom, prix: prix, qte: 1 });
    }

    SONS.ajout();
    if (bouton) {
      bouton.classList.remove('pulse');
      void bouton.offsetWidth;          // force le redemarrage de l'animation
      bouton.classList.add('pulse');
    }
    toast(nom + ' ajout\u00e9');
    majPanier();
  }

  function changer(id, delta) {
    for (var i = 0; i < PANIER.length; i++) {
      if (PANIER[i].id !== id) continue;
      PANIER[i].qte += delta;
      if (PANIER[i].qte <= 0) { PANIER.splice(i, 1); SONS.retrait(); }
      else if (delta > 0) SONS.ajout();
      else SONS.retrait();
      break;
    }
    majPanier();
    dessinerPanier();
  }

  function totalPanier() {
    var t = 0;
    for (var i = 0; i < PANIER.length; i++) t += PANIER[i].prix * PANIER[i].qte;
    return t;
  }

  function nbArticles() {
    var n = 0;
    for (var i = 0; i < PANIER.length; i++) n += PANIER[i].qte;
    return n;
  }

  function majPanier() {
    var n = nbArticles();
    var f = $('#panier-flot');
    if (f) {
      f.classList.toggle('on', n > 0);
      $('#flot-nb').textContent = n;
      $('#flot-total').textContent = eur(totalPanier());
      f.setAttribute('aria-label',
        'Voir ma commande, ' + n + ' article' + (n > 1 ? 's' : '') +
        ', total ' + eur(totalPanier()));
    }
    try {
      sessionStorage.setItem('trattoria_panier', JSON.stringify(PANIER));
    } catch (e) { }
  }

  function dessinerPanier() {
    var c = $('#panier-corps');
    if (!c) return;
    if (!PANIER.length) {
      c.innerHTML = '<p style="text-align:center;color:var(--gris);padding:40px 0">' +
        'Votre commande est vide.<br>Parcourez la carte pour la remplir.</p>';
      $('#panier-pied').style.display = 'none';
      return;
    }
    $('#panier-pied').style.display = 'block';
    var h = '';
    for (var i = 0; i < PANIER.length; i++) {
      var l = PANIER[i];
      h += '<div class="lg-panier">' +
        '<span class="nm">' + echap(l.nom) + '</span>' +
        '<span class="qte">' +
        '<button type="button" data-moins="' + echap(l.id) + '" aria-label="Retirer un ' + echap(l.nom) + '">\u2212</button>' +
        '<span>' + l.qte + '</span>' +
        '<button type="button" data-plus="' + echap(l.id) + '" aria-label="Ajouter un ' + echap(l.nom) + '">+</button>' +
        '</span>' +
        '<span class="px">' + eur(l.prix * l.qte) + '</span>' +
        '</div>';
    }
    c.innerHTML = h;
    $('#panier-total').textContent = eur(totalPanier());
  }

  function echap(s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  // ==========================================================
  //  Tiroir
  // ==========================================================
  var dernierFocus = null;
  function ouvrirTiroir() {
    dernierFocus = document.activeElement;
    $('#tiroir').classList.add('on');
    $('#tiroir').setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'hidden';
    dessinerPanier();
    SONS.clic();
    var f = $('#tiroir .fermer');
    if (f) f.focus();
  }
  function fermerTiroir() {
    $('#tiroir').classList.remove('on');
    $('#tiroir').setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';
    if (dernierFocus) dernierFocus.focus();
  }

  // ==========================================================
  //  Creneaux de retrait
  // ==========================================================
  function creneaux() {
    var out = [];
    var maintenant = new Date();
    var h = maintenant.getHours(), m = maintenant.getMinutes();
    // premier creneau : dans 25 minutes, arrondi au quart d'heure
    var t = h * 60 + m + 25;
    t = Math.ceil(t / 15) * 15;
    for (var i = 0; i < 20; i++) {
      var min = t + i * 15;
      var hh = Math.floor(min / 60), mm = min % 60;
      if (hh > 22 || (hh === 22 && mm > 0)) break;
      if (hh < 11) continue;
      if (hh >= 14 && hh < 18) continue;     // fermeture entre les services
      out.push((hh < 10 ? '0' : '') + hh + 'h' + (mm < 10 ? '0' : '') + mm);
    }
    return out;
  }

  function dessinerCreneaux() {
    var z = $('#creneaux');
    if (!z) return;
    var l = creneaux();
    if (!l.length) {
      z.innerHTML = '<p class="aide">Le service est termin\u00e9 pour aujourd\'hui. ' +
        'Vous pouvez nous appeler pour commander demain.</p>';
      return;
    }
    var h = '';
    for (var i = 0; i < l.length; i++) {
      h += '<button type="button" class="creneau" data-creneau="' + l[i] +
        '" aria-pressed="false">' + l[i] + '</button>';
    }
    z.innerHTML = h;
  }

  // ==========================================================
  //  Envoi de la commande
  // ==========================================================
  function valider() {
    var nom = $('#cl-nom'), tel = $('#cl-tel'), cgv = $('#cl-cgv');
    var ok = true;

    [nom, tel].forEach(function (ch) {
      var vide = !ch.value.trim();
      ch.setAttribute('aria-invalid', vide ? 'true' : 'false');
      var e = $('#err-' + ch.id);
      if (e) e.textContent = vide ? 'Ce champ est n\u00e9cessaire pour vous rappeler.' : '';
      if (vide) ok = false;
    });

    var numero = tel.value.replace(/[^0-9+]/g, '');
    if (numero && numero.length < 10) {
      tel.setAttribute('aria-invalid', 'true');
      $('#err-cl-tel').textContent = 'Ce num\u00e9ro semble incomplet.';
      ok = false;
    }

    if (!CRENEAU) {
      $('#err-creneau').textContent = 'Choisissez une heure de retrait.';
      ok = false;
    } else $('#err-creneau').textContent = '';

    if (!cgv.checked) {
      $('#err-cgv').textContent = 'Merci d\'accepter les conditions de vente.';
      ok = false;
    } else $('#err-cgv').textContent = '';

    if (!ok) {
      SONS.refus();
      var premier = $('[aria-invalid="true"]') || $('#creneaux');
      if (premier) premier.scrollIntoView({ block: 'center' });
      toast('Il manque quelques informations');
      return;
    }

    envoyer({
      nom: nom.value.trim(),
      tel: tel.value.trim(),
      note: $('#cl-note').value.trim(),
      creneau: CRENEAU,
      lignes: PANIER,
      total: totalPanier()
    });
  }

  function ecran(html) {
    $('#panier-corps').innerHTML = html;
    $('#panier-pied').style.display = 'none';
  }

  function envoyer(cmd) {
    ecran('<div class="etat"><div class="sablier" role="status" aria-live="polite"></div>' +
      '<h3>Envoi en cours</h3><p>Nous transmettons votre commande en cuisine.</p></div>');

    if (MODE !== 'local' || !API) {
      // Site statique : aucune cuisine au bout du fil. On le dit clairement
      // plutot que de faire croire a une commande enregistree.
      setTimeout(function () { refusHorsLigne(cmd); }, 700);
      return;
    }

    var xhr = new XMLHttpRequest();
    xhr.open('POST', API + '/site/commande', true);
    xhr.setRequestHeader('Content-Type', 'application/json');
    xhr.timeout = 12000;
    xhr.onload = function () {
      var r = {};
      try { r = JSON.parse(xhr.responseText); } catch (e) { }
      if (xhr.status === 200 && r.ok) succes(cmd, r);
      else refus(r, cmd);
    };
    xhr.onerror = function () { refusReseau(cmd); };
    xhr.ontimeout = function () { refusReseau(cmd); };
    xhr.send(JSON.stringify(cmd));
  }

  function succes(cmd, r) {
    SONS.succes();
    var lignes = '';
    for (var i = 0; i < cmd.lignes.length; i++) {
      lignes += '<div class="l"><span>' + cmd.lignes[i].qte + ' \u00d7 ' +
        echap(cmd.lignes[i].nom) + '</span><span>' +
        eur(cmd.lignes[i].prix * cmd.lignes[i].qte) + '</span></div>';
    }
    ecran('<div class="etat ok" role="status" aria-live="assertive">' +
      '<div class="pic">\u2713</div>' +
      '<h3>Commande accept\u00e9e</h3>' +
      '<p>La cuisine l\'a re\u00e7ue. Pr\u00e9sentez ce num\u00e9ro au comptoir.</p>' +
      '<div class="code-retrait">' + echap(r.code || '\u2014') + '</div>' +
      '<p><strong>Retrait \u00e0 ' + echap(cmd.creneau) + '</strong><br>' +
      'Rue de La Poste, 17100 Saintes</p>' +
      '<div class="recap">' + lignes +
      '<div class="l" style="border-top:1px solid var(--trait);margin-top:8px;padding-top:8px">' +
      '<strong>Total \u00e0 r\u00e9gler sur place</strong><strong>' + eur(cmd.total) + '</strong></div>' +
      '</div>' +
      '<p class="aide" style="margin-top:14px">Le paiement se fait au retrait, ' +
      'en esp\u00e8ces ou par carte.</p>' +
      '<button type="button" class="btn btn-s btn-bloc" style="margin-top:18px" ' +
      'onclick="location.reload()">Passer une autre commande</button>' +
      '</div>');
    PANIER = [];
    majPanier();
    try { sessionStorage.removeItem('trattoria_panier'); } catch (e) { }
  }

  /**
   * Refus renvoye par la cuisine. Chaque motif a son explication et sa
   * porte de sortie : on ne laisse jamais le client devant un mur.
   */
  function refus(r, cmd) {
    SONS.refus();
    var motif = (r && r.motif) || 'inconnu';
    var titre, texte, conseil;

    switch (motif) {
      case 'ferme':
        titre = 'Nous sommes ferm\u00e9s';
        texte = r.detail || 'Le service n\'a pas commenc\u00e9, ou il est termin\u00e9.';
        conseil = 'Consultez nos horaires plus bas, ou appelez-nous pour convenir d\'un autre moment.';
        break;
      case 'saturation':
        titre = 'La cuisine est satur\u00e9e';
        texte = r.detail || 'Trop de commandes sont en cours de pr\u00e9paration pour ce cr\u00e9neau.';
        conseil = 'Choisissez un cr\u00e9neau plus tard, ou appelez-nous : nous trouverons une solution de vive voix.';
        break;
      case 'rupture':
        titre = 'Un produit vient de manquer';
        texte = r.detail || 'Un article de votre commande n\'est plus disponible.';
        conseil = 'Retirez-le de votre commande, ou appelez-nous pour le remplacer.';
        break;
      case 'creneau':
        titre = 'Ce cr\u00e9neau n\'est plus libre';
        texte = r.detail || 'Il a \u00e9t\u00e9 pris pendant que vous choisissiez.';
        conseil = 'S\u00e9lectionnez une autre heure de retrait.';
        break;
      case 'trop_gros':
        titre = 'Commande trop importante';
        texte = r.detail || 'Cette commande d\u00e9passe ce que nous pouvons pr\u00e9parer sans pr\u00e9venir.';
        conseil = 'Pour les grandes tabl\u00e9es, appelez-nous : nous organisons cela avec plaisir.';
        break;
      default:
        titre = 'Commande non enregistr\u00e9e';
        texte = (r && r.detail) || 'Une difficult\u00e9 technique nous a emp\u00each\u00e9s de la prendre.';
        conseil = 'Le plus simple est de nous appeler, votre commande sera prise en direct.';
    }

    ecran('<div class="etat non" role="alert">' +
      '<div class="pic">\u2639</div>' +
      '<h3>' + titre + '</h3>' +
      '<p><strong>Nous en sommes sinc\u00e8rement d\u00e9sol\u00e9s.</strong></p>' +
      '<p>' + echap(texte) + '</p>' +
      '<p>' + echap(conseil) + '</p>' +
      (TEL ? '<a class="btn btn-p btn-bloc" style="margin-top:20px" href="tel:' +
        TEL.replace(/\s/g, '') + '">Appeler le restaurant</a>' : '') +
      '<button type="button" class="btn btn-s btn-bloc" style="margin-top:10px" ' +
      'id="reprendre">Revenir \u00e0 ma commande</button>' +
      '<p class="aide" style="margin-top:14px">Votre commande est conserv\u00e9e, rien n\'est perdu.</p>' +
      '</div>');
    var b = $('#reprendre');
    if (b) b.onclick = function () { dessinerPanier(); };
  }

  function refusReseau(cmd) {
    refus({ motif: 'reseau', detail: 'Le restaurant n\'a pas r\u00e9pondu. ' +
      'Votre connexion ou la n\u00f4tre a peut-\u00eatre faibli.' }, cmd);
  }

  function refusHorsLigne(cmd) {
    SONS.alerte();
    ecran('<div class="etat non" role="alert">' +
      '<div class="pic">\u260e</div>' +
      '<h3>Commande par t\u00e9l\u00e9phone</h3>' +
      '<p><strong>Nous sommes d\u00e9sol\u00e9s pour ce d\u00e9tour.</strong></p>' +
      '<p>La prise de commande en ligne n\'est active que lorsque le ' +
      'restaurant est ouvert et connect\u00e9. Ce n\'est pas le cas en ce moment.</p>' +
      '<p>Appelez-nous : nous prenons votre commande en direct, ' +
      'et elle sera pr\u00eate \u00e0 l\'heure que vous voulez.</p>' +
      (TEL ? '<a class="btn btn-p btn-bloc" style="margin-top:20px" href="tel:' +
        TEL.replace(/\s/g, '') + '">Appeler le restaurant</a>' : '') +
      '<button type="button" class="btn btn-s btn-bloc" style="margin-top:10px" ' +
      'id="reprendre">Revoir ma commande</button>' +
      '<div class="recap" style="margin-top:18px"><strong>\u00c0 nous dicter :</strong><br>' +
      recapTexte(cmd) + '</div>' +
      '</div>');
    var b = $('#reprendre');
    if (b) b.onclick = function () { dessinerPanier(); };
  }

  function recapTexte(cmd) {
    var s = '';
    for (var i = 0; i < cmd.lignes.length; i++)
      s += cmd.lignes[i].qte + ' \u00d7 ' + echap(cmd.lignes[i].nom) + '<br>';
    s += '<strong>Total ' + eur(cmd.total) + '</strong> \u2014 retrait ' + echap(cmd.creneau);
    return s;
  }

  // ==========================================================
  //  Reservation de table
  // ==========================================================
  function reserver(e) {
    e.preventDefault();
    var nom = $('#rs-nom'), tel = $('#rs-tel'), date = $('#rs-date'),
        heure = $('#rs-heure'), couverts = $('#rs-couverts');
    var ok = true;
    [nom, tel, date, heure].forEach(function (ch) {
      var vide = !ch.value.trim();
      ch.setAttribute('aria-invalid', vide ? 'true' : 'false');
      if (vide) ok = false;
    });
    if (!ok) {
      SONS.refus();
      $('#rs-msg').innerHTML = '<p class="err">Merci de compl\u00e9ter les champs signal\u00e9s.</p>';
      return;
    }

    var data = {
      nom: nom.value.trim(), tel: tel.value.trim(), date: date.value,
      heure: heure.value, couverts: parseInt(couverts.value, 10) || 2,
      note: $('#rs-note').value.trim()
    };

    if (MODE !== 'local' || !API) {
      SONS.alerte();
      $('#rs-msg').innerHTML = '<div class="carte-bloc" style="margin-top:16px">' +
        '<h3>Confirmation par t\u00e9l\u00e9phone</h3>' +
        '<p>Nous ne pouvons pas confirmer votre table automatiquement en ce moment. ' +
        'Appelez-nous, nous la r\u00e9servons imm\u00e9diatement.</p>' +
        (TEL ? '<a class="btn btn-p btn-bloc" style="margin-top:12px" href="tel:' +
          TEL.replace(/\s/g, '') + '">Appeler pour r\u00e9server</a>' : '') +
        '</div>';
      return;
    }

    $('#rs-msg').innerHTML = '<p class="aide">Envoi en cours\u2026</p>';
    var xhr = new XMLHttpRequest();
    xhr.open('POST', API + '/site/reservation', true);
    xhr.setRequestHeader('Content-Type', 'application/json');
    xhr.timeout = 12000;
    xhr.onload = function () {
      var r = {};
      try { r = JSON.parse(xhr.responseText); } catch (e) { }
      if (xhr.status === 200 && r.ok) {
        SONS.succes();
        $('#rs-msg').innerHTML = '<div class="carte-bloc" style="margin-top:16px;' +
          'border-left:4px solid var(--vert)"><h3 style="color:var(--vert)">' +
          'Demande envoy\u00e9e</h3><p>Nous vous rappelons rapidement au ' +
          echap(data.tel) + ' pour confirmer votre table de ' + data.couverts +
          ' couverts.</p><p class="aide">Tant que nous ne vous avons pas ' +
          'rappel\u00e9, la table n\'est pas garantie.</p></div>';
        $('#form-reservation').reset();
      } else {
        SONS.refus();
        $('#rs-msg').innerHTML = '<div class="carte-bloc" style="margin-top:16px;' +
          'border-left:4px solid var(--rouge)"><h3 style="color:var(--rouge)">' +
          'Demande non enregistr\u00e9e</h3><p>' +
          echap((r && r.detail) || 'Nous n\'avons pas pu enregistrer votre demande.') +
          '</p><p>Appelez-nous, c\'est imm\u00e9diat.</p>' +
          (TEL ? '<a class="btn btn-p btn-bloc" style="margin-top:12px" href="tel:' +
            TEL.replace(/\s/g, '') + '">Appeler</a>' : '') + '</div>';
      }
    };
    xhr.onerror = xhr.ontimeout = function () {
      SONS.refus();
      $('#rs-msg').innerHTML = '<p class="err">Le restaurant n\'a pas r\u00e9pondu. ' +
        'Merci de nous appeler.</p>';
    };
    xhr.send(JSON.stringify(data));
  }

  // ==========================================================
  //  Filtres de la carte
  // ==========================================================
  function filtrer(critere, bouton) {
    $$('.filtre').forEach(function (b) {
      b.setAttribute('aria-pressed', b === bouton ? 'true' : 'false');
    });
    var visibles = 0;
    $$('.plat').forEach(function (p) {
      var ok = critere === 'tout' || (p.dataset.tags || '').indexOf(critere) >= 0;
      p.classList.toggle('masque', !ok);
      if (ok) visibles++;
    });
    // une famille entierement masquee ne doit pas laisser son titre orphelin
    $$('.famille').forEach(function (f) {
      var reste = f.querySelectorAll('.plat:not(.masque)').length;
      f.style.display = reste ? '' : 'none';
    });
    SONS.clic();
    var n = $('#nb-visibles');
    if (n) n.textContent = visibles + (visibles > 1 ? ' plats' : ' plat');
  }

  // ==========================================================
  //  Pages legales
  // ==========================================================
  function ouvrirLegal(id) {
    $$('.legal').forEach(function (p) { p.classList.remove('on'); });
    var p = document.getElementById(id);
    if (!p) return;
    $$('main > section').forEach(function (s) { s.style.display = 'none'; });
    p.classList.add('on');
    p.style.display = 'block';
    window.scrollTo(0, 0);
    history.replaceState(null, '', '#' + id);
  }
  function fermerLegal() {
    $$('.legal').forEach(function (p) { p.classList.remove('on'); p.style.display = 'none'; });
    $$('main > section:not(.legal)').forEach(function (s) { s.style.display = ''; });
    history.replaceState(null, '', '#');
    window.scrollTo(0, 0);
  }

  // ==========================================================
  //  Horaires : mise en evidence du jour
  // ==========================================================
  function marquerJour() {
    var j = new Date().getDay();           // 0 = dimanche
    var idx = j === 0 ? 6 : j - 1;
    var li = $$('#horaires li');
    if (li[idx]) li[idx].classList.add('auj');
  }

  // ==========================================================
  //  Demarrage
  // ==========================================================
  function init() {
    // Restauration d'un panier laisse en plan.
    // Le contenu vient du stockage du navigateur : il a pu etre modifie
    // a la main. On revalide chaque ligne contre la carte affichee, et
    // on reprend le prix du DOM plutot que celui memorise.
    try {
      var brut = JSON.parse(sessionStorage.getItem('trattoria_panier') || '[]');
      PANIER = [];
      if (Object.prototype.toString.call(brut) === '[object Array]') {
        for (var i = 0; i < brut.length && PANIER.length < 40; i++) {
          var l = brut[i];
          if (!l || typeof l.id !== 'string') continue;
          var bouton = document.querySelector(
              '[data-ajout="' + l.id.replace(/["\\]/g, '') + '"]');
          if (!bouton) continue;                       // plat retire de la carte
          var q = parseInt(l.qte, 10);
          if (!(q > 0)) continue;
          PANIER.push({
            id: l.id,
            nom: bouton.dataset.nom,                   // libelle officiel
            prix: parseFloat(bouton.dataset.prix) || 0, // prix officiel
            qte: Math.min(q, 30)
          });
        }
      }
    } catch (e) { PANIER = []; }
    majPanier();

    document.addEventListener('click', function (e) {
      var t = e.target;

      var aj = t.closest('[data-ajout]');
      if (aj) {
        ajouter(aj.dataset.ajout, aj.dataset.nom, parseFloat(aj.dataset.prix), aj);
        return;
      }
      if (t.closest('#panier-flot')) { ouvrirTiroir(); return; }
      if (t === $('#tiroir') || t.closest('.voile') || t.closest('.fermer')) { fermerTiroir(); return; }

      var moins = t.closest('[data-moins]');
      if (moins) { changer(moins.dataset.moins, -1); return; }
      var plus = t.closest('[data-plus]');
      if (plus) { changer(plus.dataset.plus, 1); return; }

      var f = t.closest('.filtre');
      if (f) { filtrer(f.dataset.filtre, f); return; }

      var cr = t.closest('[data-creneau]');
      if (cr) {
        $$('[data-creneau]').forEach(function (b) { b.setAttribute('aria-pressed', 'false'); });
        cr.setAttribute('aria-pressed', 'true');
        CRENEAU = cr.dataset.creneau;
        $('#err-creneau').textContent = '';
        SONS.clic();
        return;
      }

      if (t.closest('#valider')) { valider(); return; }

      var lg = t.closest('[data-legal]');
      if (lg) { e.preventDefault(); ouvrirLegal(lg.dataset.legal); SONS.clic(); return; }
      if (t.closest('[data-fermer-legal]')) { e.preventDefault(); fermerLegal(); return; }
    });

    document.addEventListener('keydown', function (e) {
      if ((e.key === 'Enter' || e.key === ' ') && e.target.closest('#panier-flot')) {
        e.preventDefault(); ouvrirTiroir(); return;
      }
      if (e.key === 'Escape' && $('#tiroir').classList.contains('on')) fermerTiroir();
    });

    var fr = $('#form-reservation');
    if (fr) fr.addEventListener('submit', reserver);

    var d = $('#rs-date');
    if (d) {
      var au = new Date();
      d.min = au.toISOString().slice(0, 10);
      au.setMonth(au.getMonth() + 3);
      d.max = au.toISOString().slice(0, 10);
    }

    dessinerCreneaux();
    marquerJour();

    if (location.hash && location.hash.length > 1) {
      var cible = location.hash.slice(1);
      if (document.getElementById(cible) &&
          document.getElementById(cible).classList.contains('legal'))
        ouvrirLegal(cible);
    }

    // etat du service, uniquement en mode local
    if (MODE === 'local' && API) {
      var x = new XMLHttpRequest();
      x.open('GET', API + '/site/etat', true);
      x.timeout = 5000;
      x.onload = function () {
        try {
          var r = JSON.parse(x.responseText);
          var b = $('#etat-service');
          if (b && r.message) {
            b.textContent = r.message;
            b.style.display = 'block';
            b.style.background = r.ouvert ? 'var(--vert)' : 'var(--gris)';
          }
        } catch (e) { }
      };
      x.send();
    }
  }

  if (document.readyState === 'loading')
    document.addEventListener('DOMContentLoaded', init);
  else init();

  // expose pour les tests
  window.TrattoriaSite = {
    creneaux: creneaux, eur: eur, ajouter: ajouter,
    panier: function () { return PANIER; },
    total: totalPanier
  };
})();

